// Canonical validator/enricher for the SUPERVISOR-owned edges (spec §3.3, §6):
//   Intake -> Triage (set priority)
//   Triage -> Dispatch (require assigned_technician, optional provisional eta)
//   Close  -> Triage  (reopen; clear assignment + eta)
// status_update embeds equivalent rules; teams that prefer a separate callable
// unit can delegate the supervisor edges here. Input: { ticket, to_status,
// actor, priority, assigned_technician, eta, note }. Output: { updated } or { __error }.
const i = $input.first().json;
const ticket = i.ticket;
const from = ticket.status;
const to = i.to_status;
const now = new Date().toISOString();

const SUP_EDGES = { 'Intake': 'Triage', 'Triage': 'Dispatch', 'Close': 'Triage' };
if (SUP_EDGES[from] !== to)
  return [{ json: { __error: { code: 'ILLEGAL_TRANSITION', message: `Edge no soportado por triage_dispatch: ${from} -> ${to}.` } } }];
if ((i.actor || '').split(':')[0] !== 'supervisor')
  return [{ json: { __error: { code: 'FORBIDDEN', message: 'Solo un supervisor puede ejecutar estas transiciones.' } } }];

const patch = { status: to, updated_at: now };
if (to === 'Triage') {
  patch.priority = ['low','normal','high'].includes(i.priority) ? i.priority : (ticket.priority || 'normal');
  if (from === 'Close') { patch.assigned_technician = null; patch.eta = null; } // reopen reset
}
if (to === 'Dispatch') {
  if (!i.assigned_technician)
    return [{ json: { __error: { code: 'VALIDATION_FAILED', message: 'assigned_technician es obligatorio.', fields: { assigned_technician: 'Obligatorio.' } } } }];
  patch.assigned_technician = i.assigned_technician;
  if (i.eta) patch.eta = i.eta;
}

const audit = (ticket.audit_log || []).concat([{ at: now, actor: i.actor, from_status: from, to_status: to, note: i.note || null }]);
const EVT = { 'Triage': 'fsc.v1.ticket.triaged', 'Dispatch': 'fsc.v1.ticket.dispatched' };
const TPL = { 'Dispatch': 'T2' }; // Triage does not notify the customer (§7.1)
const updated = Object.assign({}, ticket, patch, { audit_log: audit });
return [{ json: { updated, event_name: EVT[to], notify_template: TPL[to] || null } }];
